import { useEffect, useMemo, useState } from 'react';

// ---- inlined from stringsearch ----
/**
 * Comparison-event traces for naive and Boyer-Moore string search over one fixed text.
 * Boyer-Moore is the classic simplified form: right-to-left scan, bad-character rule.
 */

const TEXT = 'VISUALIZING ALGORITHMS REVEALS THE HIDDEN CHARACTER OF EVERY PROCEDURE';
const PATTERN = 'PROCEDURE';

interface Probe {
  /** Where the pattern's left edge sits in the text for this comparison. */
  shift: number;
  /** The text position examined. */
  textIndex: number;
  match: boolean;
}

interface SearchRun {
  probes: Probe[];
  foundAt: number;
}

function naive(text: string, pattern: string): SearchRun {
  const probes: Probe[] = [];
  for (let shift = 0; shift + pattern.length <= text.length; ++shift) {
    let j = 0;
    while (j < pattern.length) {
      const match = text[shift + j] === pattern[j];
      probes.push({ shift, textIndex: shift + j, match });
      if (!match) break;
      ++j;
    }
    if (j === pattern.length) return { probes, foundAt: shift };
  }
  return { probes, foundAt: -1 };
}

function boyerMoore(text: string, pattern: string): SearchRun {
  const probes: Probe[] = [];
  const last = new Map<string, number>();
  for (let j = 0; j < pattern.length; ++j) last.set(pattern[j], j);

  let shift = 0;
  while (shift + pattern.length <= text.length) {
    let j = pattern.length - 1;
    while (j >= 0) {
      const match = text[shift + j] === pattern[j];
      probes.push({ shift, textIndex: shift + j, match });
      if (!match) break;
      --j;
    }
    if (j < 0) return { probes, foundAt: shift };
    shift += Math.max(1, j - (last.get(text[shift + j]) ?? -1));
  }
  return { probes, foundAt: -1 };
}

const naiveRun = naive(TEXT, PATTERN);
const boyerMooreRun = boyerMoore(TEXT, PATTERN);

const TICK_MS = 80;
const HOLD_TICKS = 36;
const MATCH = '#3fa66a';
const MISMATCH = '#e0538a';

const RUNS: { name: string; run: SearchRun }[] = [
  { name: 'Naive', run: naiveRun },
  { name: 'Boyer-Moore', run: boyerMooreRun }
];

const maxTicks = Math.max(...RUNS.map(({ run }) => run.probes.length));

export default function StringSearch({ width }: { width: number }) {
  const glyph = Math.max(1, width) / (TEXT.length + 2);
  const fontSize = glyph * 1.45;
  const rowHeight = fontSize * 1.6;
  const blockHeight = 16 + rowHeight * 2 + 8;
  const height = Math.round(2 * blockHeight + 12);
  const margin = glyph;

  // The SSR frame is both searches finished; the effect rewinds and replays them.
  const [tick, setTick] = useState(maxTicks);

  useEffect(() => {
    const end = maxTicks + HOLD_TICKS;
    setTick(0);
    const id = window.setInterval(() => setTick((t) => (t >= end ? 0 : t + 1)), TICK_MS);
    return () => window.clearInterval(id);
  }, []);

  const blocks = useMemo(
    () =>
      RUNS.map(({ name, run }) => {
        const shown = Math.min(tick, run.probes.length);
        const examined = new Set<number>();
        for (let k = 0; k < shown; ++k) examined.add(run.probes[k].textIndex);
        const done = shown >= run.probes.length;
        const current = shown > 0 && !done ? run.probes[shown - 1] : null;
        const shift = done ? run.foundAt : shown > 0 ? run.probes[shown - 1].shift : 0;
        return { name, run, shown, examined, done, current, shift };
      }),
    [tick]
  );

  if (width === 0) return null;

  const charX = (i: number) => margin + (i + 0.5) * glyph;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Naive and Boyer-Moore string search racing over the same text, one comparison per tick. Letters gray out as they are read; Boyer-Moore's bad-character rule leaps whole pattern-lengths, finishing while naive still crawls, and most of its text is never examined at all"
    >
      {blocks.map((block, b) => {
        const top = b * blockHeight + 4;
        const textY = top + 16 + fontSize;
        const patternY = textY + rowHeight;
        return (
          <g key={block.name} fontFamily="ui-monospace, SFMono-Regular, Menlo, monospace">
            <text x={margin} y={top + 11} fill="var(--text)" fontSize={11} fontWeight={600} fontFamily="inherit">
              {block.name}
            </text>
            <text x={width - margin} y={top + 11} textAnchor="end" fill="var(--muted)" fontSize={11}>
              {`${block.shown} comparisons · ${block.examined.size} of ${TEXT.length} letters read`}
            </text>
            {block.done && (
              <rect
                x={margin + block.run.foundAt * glyph}
                y={textY - fontSize}
                width={PATTERN.length * glyph}
                height={fontSize * 1.3}
                fill={MATCH}
                opacity={0.25}
                rx={2}
              />
            )}
            {block.current && (
              <>
                <rect
                  x={margin + block.current.textIndex * glyph}
                  y={textY - fontSize}
                  width={glyph}
                  height={fontSize * 1.3}
                  fill={block.current.match ? MATCH : MISMATCH}
                  opacity={0.4}
                />
                <rect
                  x={margin + block.current.textIndex * glyph}
                  y={patternY - fontSize}
                  width={glyph}
                  height={fontSize * 1.3}
                  fill={block.current.match ? MATCH : MISMATCH}
                  opacity={0.4}
                />
              </>
            )}
            {[...TEXT].map((letter, i) => (
              <text
                key={i}
                x={charX(i)}
                y={textY}
                textAnchor="middle"
                fontSize={fontSize}
                fill={block.examined.has(i) ? 'var(--muted)' : 'var(--text)'}
                opacity={block.examined.has(i) ? 0.55 : 1}
              >
                {letter}
              </text>
            ))}
            {[...PATTERN].map((letter, j) => (
              <text
                key={j}
                x={charX(block.shift + j)}
                y={patternY}
                textAnchor="middle"
                fontSize={fontSize}
                fontWeight={600}
                fill="var(--accent)"
              >
                {letter}
              </text>
            ))}
          </g>
        );
      })}
    </svg>
  );
}
